1	// ============================================================================
2	// FreeLang Query Runner 모듈 - 통합 쿼리 실행 파이프라인
3	// ============================================================================
4	// 목표: planner→physical_plan→executor→result_set 통합 파이프라인 facade
5	// 원리:
6	//   1. QueryRunner: 모든 실행 단계를 통합 관리
7	//   2. query_runner_execute: SQL 문자열 → 파싱 → 계획 → 실행 → 결과
8	//   3. 에러 처리: 각 단계별 에러 코드 전파 (QR_ERR_*)
9	// 구조:
10	//   - 상수 정의 (에러 코드, 제한값)
11	//   - PipelineStats, QueryRunner 구조체
12	//   - 초기화 및 실행 함수 (8개 공개 API)
13	//   - 헬퍼 함수
14	// ============================================================================
15	
16	module query_runner {
17	    // === 에러 코드 (170-172) ===
18	    const QR_OK:        i32 = 0;
19	    const QR_ERR_PLAN:  i32 = 170;
20	    const QR_ERR_EXEC:  i32 = 171;
21	    const QR_ERR_PARSE: i32 = 172;
22	
23	    // === 제한값 ===
24	    const MAX_RESULT_ROWS: i32 = 1024;
25	
26	    // === 데이터 구조체 ===
27	
28	    // 파이프라인 통계 및 상태
29	    struct PipelineStats {
30	        parse_ok:    bool;
31	        plan_type:   i32;
32	        op_count:    i32;
33	        result_rows: i32;
34	        error_code:  i32;
35	    }
36	
37	    // 통합 쿼리 실행 엔진
38	    struct QueryRunner {
39	        pq:        query_parser.ParsedQuery;
40	        exec_plan: planner.ExecPlan;
41	        phys_plan: physical_plan.PhysicalPlan;
42	        ex:        executor.Executor;
43	        result:    result_set.ResultSet;
44	        stats:     PipelineStats;
45	        has_error: bool;
46	        error_code: i32;
47	    }
48	
49	    // === 초기화 함수 ===
50	
51	    // 새로운 QueryRunner 생성 및 초기화
52	    func query_runner_new() -> QueryRunner {
53	        let qr = QueryRunner{
54	            pq:        query_parser.ParsedQuery{
55	                table_name:    "",
56	                where_col_idx: -1,
57	                where_op:      0,
58	                where_val_int: 0,
59	                order_col_idx: -1,
60	                order_desc:    false,
61	                limit_count:   -1,
62	                has_error:     false,
63	                error_code:    0,
64	            },
65	            exec_plan: planner.ExecPlan{
66	                plan_type:  0,
67	                index_col:  -1,
68	                est_rows:   0,
69	                cost:       0,
70	                error_code: 0,
71	            },
72	            phys_plan: physical_plan.physical_plan_new(),
73	            ex:        executor.executor_new(),
74	            result:    result_set.result_set_new(16),
75	            stats:     PipelineStats{
76	                parse_ok:    false,
77	                plan_type:   0,
78	                op_count:    0,
79	                result_rows: 0,
80	                error_code:  0,
81	            },
82	            has_error: false,
83	            error_code: QR_OK,
84	        };
85	        return qr;
86	    }
87	
88	    // === 메인 실행 함수 (핵심) ===
89	
90	    // 통합 쿼리 실행 파이프라인
91	    // SQL 문자열 → 파싱 → 계획 → 물리 계획 → 실행 → 결과
92	    func query_runner_execute(qr: *QueryRunner, t: schema.Table, sql: string) -> i32 {
93	        // 1단계: SQL 파싱
94	        qr.pq = query_parser.parse_query(sql, t);
95	        if qr.pq.has_error {
96	            qr.has_error = true;
97	            qr.error_code = QR_ERR_PARSE;
98	            qr.stats.error_code = QR_ERR_PARSE;
99	            qr.stats.parse_ok = false;
100	            return QR_ERR_PARSE;
101	        }
102	        qr.stats.parse_ok = true;
103	
104	        // 2단계: 테이블 통계 수집
105	        let stats = planner.stats_build(t);
106	
107	        // 3단계: 쿼리 구조 생성 및 비용 기반 실행 계획 수립
108	        let q = query.query_table(t);
109	
110	        // WHERE 절 추가 (파서에서 추출된 정보 사용)
111	        if qr.pq.where_col_idx >= 0 {
112	            let col_type = t.schema.col_defs[qr.pq.where_col_idx].col_type;
113	
114	            // INT 컬럼 조건 추가
115	            if col_type == schema.COL_TYPE_INT {
116	                let op_val = qr.pq.where_op;
117	                // 파서의 연산자 코드를 query.fl의 코드로 매핑
118	                let mapped_op = op_val;  // 같은 코드 체계 사용
119	                q.where_int(qr.pq.where_col_idx, mapped_op, qr.pq.where_val_int);
120	            }
121	        }
122	
123	        // ORDER BY 설정
124	        if qr.pq.order_col_idx >= 0 {
125	            q.order_by_col(qr.pq.order_col_idx, !qr.pq.order_desc);
126	        }
127	
128	        // LIMIT 설정
129	        if qr.pq.limit_count > 0 {
130	            q.limit(qr.pq.limit_count);
131	        }
132	
133	        // 4단계: 비용 기반 실행 계획 생성
134	        qr.exec_plan = planner.plan_query(q, stats, false, false);
135	        if qr.exec_plan.error_code != planner.PLAN_OK {
136	            qr.has_error = true;
137	            qr.error_code = QR_ERR_PLAN;
138	            qr.stats.error_code = QR_ERR_PLAN;
139	            return QR_ERR_PLAN;
140	        }
141	        qr.stats.plan_type = qr.exec_plan.plan_type;
142	
143	        // 5단계: 논리 계획을 물리 계획으로 변환
144	        let phys_err = 0;
145	        (qr.phys_plan, phys_err) = physical_plan.physical_plan_from_logical(qr.exec_plan);
146	        if phys_err != physical_plan.PHYS_OK {
147	            qr.has_error = true;
148	            qr.error_code = QR_ERR_PLAN;
149	            qr.stats.error_code = QR_ERR_PLAN;
150	            return QR_ERR_PLAN;
151	        }
152	        qr.stats.op_count = qr.phys_plan.op_count;
153	
154	        // 6단계: Executor 생성 및 초기화
155	        qr.ex = executor.executor_new();
156	        let init_err = executor.executor_init(&qr.ex, qr.phys_plan, t);
157	        if init_err != executor.EXEC_OK {
158	            qr.has_error = true;
159	            qr.error_code = QR_ERR_EXEC;
160	            qr.stats.error_code = QR_ERR_EXEC;
161	            return QR_ERR_EXEC;
162	        }
163	
164	        // 7단계: 물리 계획 실행
165	        let exec_err = executor.executor_execute(&qr.ex, t);
166	        if exec_err != executor.EXEC_OK {
167	            qr.has_error = true;
168	            qr.error_code = QR_ERR_EXEC;
169	            qr.stats.error_code = QR_ERR_EXEC;
170	            return QR_ERR_EXEC;
171	        }
172	
173	        // 8단계: 결과 집합 추출 및 행 수 기록
174	        qr.result = executor.executor_get_result(&qr.ex);
175	        qr.stats.result_rows = result_set.result_set_get_row_count(&qr.result);
176	
177	        qr.has_error = false;
178	        qr.error_code = QR_OK;
179	        qr.stats.error_code = QR_OK;
180	
181	        return QR_OK;
182	    }
183	
184	    // === 결과 조회 함수 ===
185	
186	    // 쿼리 결과 집합 반환
187	    func query_runner_get_result(qr: *QueryRunner) -> result_set.ResultSet {
188	        return qr.result;
189	    }
190	
191	    // 결과 행 수 반환
192	    func query_runner_get_row_count(qr: *QueryRunner) -> i32 {
193	        return qr.stats.result_rows;
194	    }
195	
196	    // 결과를 문자열로 변환
197	    func query_runner_result_to_string(qr: *QueryRunner) -> string {
198	        return result_set.result_set_to_string(&qr.result);
199	    }
200	
201	    // === 메타데이터 함수 ===
202	
203	    // 선택된 실행 계획 타입 반환
204	    func query_runner_get_plan_type(qr: *QueryRunner) -> i32 {
205	        return qr.stats.plan_type;
206	    }
207	
208	    // === 관리 함수 ===
209	
210	    // QueryRunner 리셋 (재사용 가능하게 초기화)
211	    func query_runner_reset(qr: *QueryRunner) -> i32 {
212	        // 모든 필드 초기화
213	        qr.pq = query_parser.ParsedQuery{
214	            table_name:    "",
215	            where_col_idx: -1,
216	            where_op:      0,
217	            where_val_int: 0,
218	            order_col_idx: -1,
219	            order_desc:    false,
220	            limit_count:   -1,
221	            has_error:     false,
222	            error_code:    0,
223	        };
224	
225	        qr.exec_plan = planner.ExecPlan{
226	            plan_type:  0,
227	            index_col:  -1,
228	            est_rows:   0,
229	            cost:       0,
230	            error_code: 0,
231	        };
232	
233	        qr.phys_plan = physical_plan.physical_plan_new();
234	        qr.ex = executor.executor_new();
235	        qr.result = result_set.result_set_new(16);
236	
237	        qr.stats = PipelineStats{
238	            parse_ok:    false,
239	            plan_type:   0,
240	            op_count:    0,
241	            result_rows: 0,
242	            error_code:  0,
243	        };
244	
245	        qr.has_error = false;
246	        qr.error_code = QR_OK;
247	
248	        return QR_OK;
249	    }
250	
251	    // === 디버그 함수 ===
252	
253	    // QueryRunner 상태 문자열 표현
254	    func query_runner_stats(qr: *QueryRunner) -> string {
255	        let result = "QueryRunner {parse_ok: ";
256	
257	        if qr.stats.parse_ok {
258	            result = result + "true";
259	        } else {
260	            result = result + "false";
261	        }
262	
263	        result = result + ", plan_type: ";
264	        result = result + int_to_string(qr.stats.plan_type);
265	
266	        result = result + ", op_count: ";
267	        result = result + int_to_string(qr.stats.op_count);
268	
269	        result = result + ", result_rows: ";
270	        result = result + int_to_string(qr.stats.result_rows);
271	
272	        result = result + ", error: ";
273	        result = result + int_to_string(qr.stats.error_code);
274	
275	        result = result + "}";
276	
277	        return result;
278	    }
279	
280	    // === 헬퍼 함수 ===
281	
282	    // 정수를 문자열로 변환
283	    @inline
284	    func int_to_string(n: i32) -> string {
285	        if n == 0 {
286	            return "0";
287	        }
288	        if n < 0 {
289	            return "-" + int_to_string(-n);
290	        }
291	
292	        let digits = "";
293	        let temp = n;
294	        let digit_count = 0;
295	        let pow10 = 1;
296	
297	        // 자리수 계산
298	        while temp > 0 {
299	            digit_count = digit_count + 1;
300	            temp = temp / 10;
301	        }
302	
303	        // 10의 거듭제곱 계산
304	        temp = digit_count - 1;
305	        while temp > 0 {
306	            pow10 = pow10 * 10;
307	            temp = temp - 1;
308	        }
309	
310	        // 각 자리수 변환
311	        let idx = 0;
312	        temp = n;
313	        for idx = 0; idx < digit_count; idx = idx + 1 {
314	            let digit = (temp / pow10) % 10;
315	            if digit == 0 {
316	                digits = digits + "0";
317	            } else if digit == 1 {
318	                digits = digits + "1";
319	            } else if digit == 2 {
320	                digits = digits + "2";
321	            } else if digit == 3 {
322	                digits = digits + "3";
323	            } else if digit == 4 {
324	                digits = digits + "4";
325	            } else if digit == 5 {
326	                digits = digits + "5";
327	            } else if digit == 6 {
328	                digits = digits + "6";
329	            } else if digit == 7 {
330	                digits = digits + "7";
331	            } else if digit == 8 {
332	                digits = digits + "8";
333	            } else if digit == 9 {
334	                digits = digits + "9";
335	            }
336	            pow10 = pow10 / 10;
337	        }
338	
339	        return digits;
340	    }
341	}
