264	    // === 계획 기반 실행 ===
265	
266	    // 계획에 따라 인덱스 또는 풀스캔 사용
267	    func execute_planned(t: schema.Table, q: query.Query,
268	                        plan: ExecPlan, idx: index.BTreeIndex) -> query.QueryResult {
269	
270	        // PLAN_FULL_SCAN: 기존 query_execute 사용 (풀스캔)
271	        if plan.plan_type == PLAN_FULL_SCAN {
272	            return query.execute(t, q);
273	        }
274	
275	        // PLAN_INDEX_EQ: 정확한 인덱스 탐색
276	        if plan.plan_type == PLAN_INDEX_EQ {
277	            let result = query.QueryResult{
278	                row_indices: make([i32], 1024),
279	                row_count:   0,
280	                agg_value:   0,
281	                error_code:  query.QUERY_OK,
282	            };
283	
284	            let search_val = q.wheres[0].int_val;
285	            let found_row_id, found = idx.index_search(search_val);
286	
287	            // 인덱스에서 찾은 row_id를 테이블 행 인덱스로 변환
288	            if found {
289	                let row_idx = 0;
290	                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
291	                    if t.row_ids[row_idx] == found_row_id && !t.deleted_flags[row_idx] {
292	                        result.row_indices[0] = row_idx;
293	                        result.row_count = 1;
294	                        break;
295	                    }
296	                }
297	            }
298	
299	            return result;
300	        }
301	
302	        // PLAN_INDEX_RANGE: 범위 탐색
303	        if plan.plan_type == PLAN_INDEX_RANGE {
304	            let result = query.QueryResult{
305	                row_indices: make([i32], 1024),
306	                row_count:   0,
307	                agg_value:   0,
308	                error_code:  query.QUERY_OK,
309	            };
310	
311	            let min_val = q.wheres[0].int_val;
312	            let op = q.wheres[0].op;
313	            let max_val = min_val + 100;  // 범위 크기 (간단화)
314	
315	            // 인덱스 검증: idx가 유효한지 확인
316	            if idx.key_count == 0 {
317	                // 인덱스가 비어있으면 풀스캔 대신 빈 결과 반환
318	                return result;
319	            }
320	
321	            // index_range() 호출: min_val ~ max_val 범위의 row_id 배열 반환
322	            let row_id_array, row_id_count = idx.index_range(min_val, max_val);
323	
324	            // 반환된 row_id를 테이블의 행 인덱스로 변환
325	            let i = 0;
326	            for i = 0; i < row_id_count && result.row_count < 1024; i = i + 1 {
327	                let target_row_id = row_id_array[i];
328	
329	                // row_id를 행 인덱스로 매핑
330	                let row_idx = 0;
331	                for row_idx = 0; row_idx < t.row_count; row_idx = row_idx + 1 {
332	                    if t.row_ids[row_idx] == target_row_id && !t.deleted_flags[row_idx] {
333	                        // 행 조건에 추가로 WHERE 조건 검증 (이중 검증)
334	                        let soa_idx = plan.index_col * MAX_ROWS + row_idx;
335	                        let val = t.int_cols[soa_idx];
336	
337	                        let matches = false;
338	                        if op == query.OP_GT {
339	                            matches = val > min_val;
340	                        } else if op == query.OP_LT {
341	                            matches = val < min_val;
342	                        } else if op == query.OP_GE {
343	                            matches = val >= min_val;
344	                        } else if op == query.OP_LE {
345	                            matches = val <= min_val;
346	                        }
347	
348	                        if matches {
349	                            result.row_indices[result.row_count] = row_idx;
350	                            result.row_count = result.row_count + 1;
351	                        }
352	                        break;
353	                    }
354	                }
355	            }
356	
357	            return result;
358	        }
359	
360	        // PLAN_INDEX_LIKE: 문자열 접두어 탐색
361	        if plan.plan_type == PLAN_INDEX_LIKE {
362	            let result = query.QueryResult{
363	                row_indices: make([i32], 1024),
364	                row_count:   0,
365	                agg_value:   0,
366	                error_code:  query.QUERY_OK,
367	            };
368	
369	            // 문자열 인덱스 사용 (아직 미구현, 풀스캔 대신)
370	            // 여기서는 간단화하여 풀스캔 로직 사용
371	            let prefix = q.wheres[0].str_val;
372	            let i = 0;
373	            for i = 0; i < t.row_count && result.row_count < 1024; i = i + 1 {
374	                if t.deleted_flags[i] {
375	                    continue;
376	                }
377	
378	                let soa_idx = plan.index_col * MAX_ROWS + i;
379	                let str_val = t.str_cols[soa_idx];
380	
381	                // 접두어 매칭 (간단 구현)
382	                if str_prefix_match(str_val, prefix) {
383	                    result.row_indices[result.row_count] = i;
384	                    result.row_count = result.row_count + 1;
385	                }
386	            }
387	
388	            return result;
389	        }
390	
391	        // 기본: 풀스캔
392	        return query.execute(t, q);
393	    }
