395	    // === 문자열 유틸리티 ===
396	
397	    // 문자열 접두어 매칭
398	    @inline
399	    func str_prefix_match(str_val: string, prefix: string) -> bool {
400	        let str_len = 0;
401	        let i = 0;
402	        for i = 0; i < 256; i = i + 1 {
403	            if str_val[i:i+1] == "" {
404	                str_len = i;
405	                break;
406	            }
407	        }
408	
409	        let prefix_len = 0;
410	        for i = 0; i < 256; i = i + 1 {
411	            if prefix[i:i+1] == "" {
412	                prefix_len = i;
413	                break;
414	            }
415	        }
416	
417	        if prefix_len > str_len {
418	            return false;
419	        }
420	
421	        let j = 0;
422	        for j = 0; j < prefix_len; j = j + 1 {
423	            if str_val[j:j+1] != prefix[j:j+1] {
424	                return false;
425	            }
426	        }
427	
428	        return true;
429	    }
