435	        let type_str = "UNKNOWN";
436	        if plan.plan_type == PLAN_FULL_SCAN {
437	            type_str = "FULL_SCAN";
438	        } else if plan.plan_type == PLAN_INDEX_EQ {
439	            type_str = "INDEX_EQ";
440	        } else if plan.plan_type == PLAN_INDEX_RANGE {
441	            type_str = "INDEX_RANGE";
442	        } else if plan.plan_type == PLAN_INDEX_LIKE {
443	            type_str = "INDEX_LIKE";
444	        }
445	
446	        // 간단 포맷: "PLAN_TYPE(est_rows:N, cost:C)"
447	        return type_str;
448	    }
