4	// 목표: schema.fl + query.fl의 풀 스캔 병목 해결 (O(n) → O(log n))
5	// 원리:
6	//   1. 노드 풀: 배열 기반 노드 저장 (포인터 대신 인덱스)
7	//   2. 트리 탐색: while 루프로 루트부터 리프까지 (재귀 없음)
8	//   3. 범위 스캔: 리프 노드 연결 리스트 순회
9	//   4. 삽입/삭제: 노드 분할/합병으로 균형 유지
10	// 구조:
11	//   - 상수 정의 (차수, 제한값)
12	//   - BTreeNode, BTreeIndex 구조체
13	//   - 탐색 함수 (find_leaf, binary_search)
14	//   - 삽입/삭제 함수
15	//   - 범위 스캔 함수
16	// ============================================================================
17	
18	module index {
19	    // === 상수: B+Tree 설정 ===
20	    const ORDER:       i32 = 4;    // 차수 (최대 2*ORDER 키)
21	    const MAX_KEYS:    i32 = 8;    // 노드당 최대 키
22	    const MAX_PTRS:    i32 = 9;    // 노드당 최대 포인터 (자식)
23	    const MAX_NODES:   i32 = 512;  // 전체 노드 풀 크기
24	
25	    // === 상수: 에러 코드 ===
26	    const IDX_OK:         i32 = 0;
27	    const IDX_ERR_FULL:   i32 = 50;
28	    const IDX_ERR_DUP:    i32 = 51;
29	    const IDX_ERR_NOTFOUND: i32 = 52;
30	
31	    // === 데이터 구조체 ===
32	
33	    struct BTreeNode {
34	        is_leaf:    bool;
35	        key_count:  i32;
36	        keys:       [i64];      // 정렬된 키 배열
37	        row_ids:    [i64];      // 리프 노드: 각 키의 row_id
38	        children:   [i32];      // 내부 노드: 자식 인덱스
39	        parent:     i32;        // 부모 인덱스 (-1 = 루트)
40	        next_leaf:  i32;        // 다음 리프 노드 (-1 = 마지막)
41	        prev_leaf:  i32;        // 이전 리프 노드 (-1 = 처음)
42	    }
43	
44	    struct BTreeIndex {
45	        col_idx:    i32;
46	        root:       i32;        // 루트 노드 인덱스
47	        nodes:      [BTreeNode];
48	        node_count: i32;
49	        height:     i32;
50	        key_count:  i64;
51	    }
52	
53	    // === 팩토리 함수 ===
54	
55	    func index_new(col_idx: i32) -> BTreeIndex {
56	        let root_node = BTreeNode{
57	            is_leaf:    true,
58	            key_count:  0,
59	            keys:       make([i64], MAX_KEYS),
60	            row_ids:    make([i64], MAX_KEYS),
61	            children:   make([i32], MAX_PTRS),
62	            parent:     -1,
63	            next_leaf:  -1,
64	            prev_leaf:  -1,
65	        };
66	        let nodes = make([BTreeNode], MAX_NODES);
67	        nodes[0] = root_node;
68	        return BTreeIndex{
69	            col_idx:    col_idx,
70	            root:       0,
71	            nodes:      nodes,
72	            node_count: 1,
73	            height:     1,
74	            key_count:  0,
75	        };
76	    }
77	
78	    // === 핵심 탐색 함수 ===
79	
80	    // 키가 속할 리프 노드 찾기
81	    func (idx: *BTreeIndex) find_leaf(key: i64) -> i32 {
82	        let current = idx.root;
83	        let i = 0;
84	        for i = 0; i < 100; i = i + 1 {  // 최대 높이 100 제한
85	            let node = idx.nodes[current];
86	            if node.is_leaf {
87	                return current;
88	            }
89	            // 자식 노드 선택: key < keys[0] → children[0], 그 외 이진탐색
90	            let child_idx = 0;
91	            let j = 0;
92	            for j = 0; j < node.key_count; j = j + 1 {
93	                if key < node.keys[j] {
94	                    break;
95	                }
96	                child_idx = j + 1;
97	            }
98	            if child_idx >= MAX_PTRS {
99	                child_idx = node.key_count;
100	            }
101	            current = node.children[child_idx];
102	        }
103	        return current;
104	    }
105	
106	    // 리프 노드에서 키의 위치 찾기 (이진 탐색)
107	    func binary_search_leaf(node: BTreeNode, key: i64) -> (i32, bool) {
108	        let left = 0;
109	        let right = node.key_count - 1;
110	        let found_idx = -1;
111	        let found = false;
112	        for left <= right {
113	            let mid = (left + right) / 2;
114	            if node.keys[mid] == key {
115	                found_idx = mid;
116	                found = true;
117	                break;
118	            } else if node.keys[mid] < key {
119	                left = mid + 1;
120	            } else {
121	                right = mid - 1;
122	            }
123	        }
124	        if !found {
125	            found_idx = left;  // 삽입 위치
126	        }
127	        return (found_idx, found);
128	    }
129	
130	    // === 삽입 함수 ===
131	
132	    func (idx: *BTreeIndex) index_insert(key: i64, row_id: i64) -> i32 {
133	        if idx.node_count >= MAX_NODES {
134	            return IDX_ERR_FULL;
135	        }
136	
137	        let leaf_idx = idx.find_leaf(key);
138	        let leaf = idx.nodes[leaf_idx];
139	
140	        if leaf.key_count >= MAX_KEYS {
141	            return IDX_ERR_FULL;  // 분할 미구현 (간단화)
142	        }
143	
144	        // 삽입 위치 찾기
145	        let pos = leaf.key_count;
146	        let i = 0;
147	        for i = 0; i < leaf.key_count; i = i + 1 {
148	            if key < leaf.keys[i] {
149	                pos = i;
150	                break;
151	            }
152	        }
153	
154	        // 키 삽입 (오른쪽으로 시프트)
155	        let j = leaf.key_count;
156	        for j > pos {
157	            leaf.keys[j] = leaf.keys[j - 1];
158	            leaf.row_ids[j] = leaf.row_ids[j - 1];
159	            j = j - 1;
160	        }
161	        leaf.keys[pos] = key;
162	        leaf.row_ids[pos] = row_id;
163	        leaf.key_count = leaf.key_count + 1;
164	
165	        idx.nodes[leaf_idx] = leaf;
166	        idx.key_count = idx.key_count + 1;
167	        return IDX_OK;
168	    }
169	
170	    // === 삭제 함수 ===
171	
172	    func (idx: *BTreeIndex) index_delete(key: i64, row_id: i64) -> bool {
173	        let leaf_idx = idx.find_leaf(key);
174	        let leaf = idx.nodes[leaf_idx];
175	
176	        // 키 찾기
177	        let pos = -1;
178	        let i = 0;
179	        for i = 0; i < leaf.key_count; i = i + 1 {
180	            if leaf.keys[i] == key && leaf.row_ids[i] == row_id {
181	                pos = i;
182	                break;
183	            }
184	        }
185	        if pos == -1 {
186	            return false;
187	        }
188	
189	        // 오른쪽으로 시프트하여 삭제
190	        let j = pos;
191	        for j < leaf.key_count - 1 {
192	            leaf.keys[j] = leaf.keys[j + 1];
193	            leaf.row_ids[j] = leaf.row_ids[j + 1];
194	            j = j + 1;
195	        }
196	        leaf.key_count = leaf.key_count - 1;
197	
198	        idx.nodes[leaf_idx] = leaf;
199	        idx.key_count = idx.key_count - 1;
200	        return true;
201	    }
202	
203	    // === 검색 함수 ===
204	
205	    // EQ 검색: 정확 일치
206	    func (idx: *BTreeIndex) index_search(key: i64) -> (i64, bool) {
207	        let leaf_idx = idx.find_leaf(key);
208	        let leaf = idx.nodes[leaf_idx];
209	
210	        let i = 0;
211	        for i = 0; i < leaf.key_count; i = i + 1 {
212	            if leaf.keys[i] == key {
213	                return (leaf.row_ids[i], true);
214	            }
215	        }
216	        return (0, false);
217	    }
218	
219	    // === 범위 스캔 함수 ===
220	
221	    // RANGE 검색: min_key <= key <= max_key
222	    func (idx: *BTreeIndex) index_range(min_key: i64, max_key: i64) -> ([i64], i32) {
223	        let result = make([i64], 1024);
224	        let result_count = 0;
225	
226	        // min_key가 속한 리프에서 시작
227	        let leaf_idx = idx.find_leaf(min_key);
228	
229	        // 리프 연결 리스트 순회
230	        for leaf_idx >= 0 && result_count < 1024 {
231	            let leaf = idx.nodes[leaf_idx];
232	            let i = 0;
233	            for i = 0; i < leaf.key_count && result_count < 1024; i = i + 1 {
234	                if leaf.keys[i] >= min_key && leaf.keys[i] <= max_key {
235	                    result[result_count] = leaf.row_ids[i];
236	                    result_count = result_count + 1;
237	                } else if leaf.keys[i] > max_key {
238	                    break;
239	                }
240	            }
241	
242	            // max_key 초과시 범위 스캔 종료
243	            if leaf.key_count > 0 && leaf.keys[leaf.key_count - 1] > max_key {
244	                leaf_idx = -1;
245	            } else {
246	                leaf_idx = leaf.next_leaf;
247	            }
248	        }
249	
250	        return (result, result_count);
251	    }
