255	    // 테이블 전체로 인덱스 재구성
256	    func (idx: *BTreeIndex) index_rebuild(t: schema.Table) -> i32 {
257	        // 기존 인덱스 초기화
258	        let root_node = BTreeNode{
259	            is_leaf:    true,
260	            key_count:  0,
261	            keys:       make([i64], MAX_KEYS),
262	            row_ids:    make([i64], MAX_KEYS),
263	            children:   make([i32], MAX_PTRS),
264	            parent:     -1,
265	            next_leaf:  -1,
266	            prev_leaf:  -1,
267	        };
268	        idx.nodes[0] = root_node;
269	        idx.root = 0;
270	        idx.node_count = 1;
271	        idx.height = 1;
272	        idx.key_count = 0;
273	
274	        // 테이블의 모든 행을 인덱스에 삽입
275	        let i = 0;
276	        for i = 0; i < t.row_count; i = i + 1 {
277	            if !t.deleted_flags[i] {
278	                let key = t.get_int_val(i, idx.col_idx);
279	                let err = idx.index_insert(key, t.row_ids[i]);
280	                if err != IDX_OK {
281	                    return err;
282	                }
283	            }
284	        }
285	        return IDX_OK;
286	    }
