4	// 목표: 문자열 컬럼에 대해 EQ/LIKE/범위 검색 지원
5	// 원리:
6	//   1. 정렬 배열: string 키를 정렬된 순서로 저장 (B+Tree 대신 간단화)
7	//   2. 이진 탐색: EQ 검색은 이진 탐색으로 O(log n)
8	//   3. LIKE 검색: 접두어 일치는 선형 탐색 (char_at 비교)
9	//   4. 범위 검색: 사전식 비교로 시작/종료 위치 찾기
10	// 구조:
11	//   - StrIndexEntry, StrIndex 구조체
12	//   - 삽입 (유지 정렬), 검색, 범위 스캔
13	// ============================================================================
14	
15	module index_str {
16	    // === 상수 ===
17	    const MAX_STR_ENTRIES: i32 = 1024;
18	
19	    // === 에러 코드 ===
20	    const STR_IDX_OK:          i32 = 0;
21	    const STR_IDX_ERR_FULL:    i32 = 60;
22	    const STR_IDX_ERR_NOTFOUND: i32 = 61;
23	
24	    // === 데이터 구조체 ===
25	
26	    struct StrIndexEntry {
27	        key:    string;
28	        row_id: i64;
29	    }
30	
31	    struct StrIndex {
32	        col_idx:     i32;
33	        entries:     [StrIndexEntry];
34	        entry_count: i32;
35	    }
36	
37	    // === 팩토리 함수 ===
38	
39	    // 새로운 문자열 인덱스 생성
40	    func str_index_new(col_idx: i32) -> StrIndex {
41	        return StrIndex{
42	            col_idx:     col_idx,
43	            entries:     make([StrIndexEntry], MAX_STR_ENTRIES),
44	            entry_count: 0,
45	        };
46	    }
47	
48	    // === 문자열 비교 함수 ===
49	
50	    // 두 문자열 비교: a < b → -1, a == b → 0, a > b → 1
51	    // 사전식(lexicographic) 순서로 비교
52	    @inline
53	    func str_cmp(a: string, b: string) -> i32 {
54	        let a_len = len(a);
55	        let b_len = len(b);
56	        let min_len = a_len;
57	        if b_len < min_len {
58	            min_len = b_len;
59	        }
60	
61	        let i = 0;
62	        for i = 0; i < min_len; i = i + 1 {
63	            let a_ch = char_at(a, i);
64	            let b_ch = char_at(b, i);
65	            if a_ch < b_ch {
66	                return -1;
67	            }
68	            if a_ch > b_ch {
69	                return 1;
70	            }
71	        }
72	
73	        if a_len < b_len {
74	            return -1;
75	        }
76	        if a_len > b_len {
77	            return 1;
78	        }
79	        return 0;
80	    }
81	
82	    // 접두어 일치 확인
83	    // "hello" starts_with "he" → true
84	    @inline
85	    func str_starts_with(str: string, prefix: string) -> bool {
86	        let plen = len(prefix);
87	        let slen = len(str);
88	        if plen > slen {
89	            return false;
90	        }
91	        let i = 0;
92	        for i = 0; i < plen; i = i + 1 {
93	            if char_at(str, i) != char_at(prefix, i) {
94	                return false;
95	            }
96	        }
97	        return true;
98	    }
99	
100	    // === 삽입 함수 (정렬 유지) ===
101	
102	    // 키-로우 쌍을 인덱스에 삽입 (정렬 순서 유지)
103	    // 실패 시 STR_IDX_ERR_FULL 반환
104	    func (si: *StrIndex) str_insert(key: string, row_id: i64) -> i32 {
105	        if si.entry_count >= MAX_STR_ENTRIES {
106	            return STR_IDX_ERR_FULL;
107	        }
108	
109	        // 삽입 위치 찾기 (정렬 순서 유지)
110	        let pos = 0;
111	        let i = 0;
112	        for i = 0; i < si.entry_count; i = i + 1 {
113	            let cmp = str_cmp(key, si.entries[i].key);
114	            if cmp < 0 {
115	                pos = i;
116	                break;
117	            }
118	            pos = i + 1;
119	        }
120	
121	        // 배열 우측 시프트 (pos 위치 뒤로 모든 원소 이동)
122	        let j = si.entry_count;
123	        for j > pos {
124	            si.entries[j] = si.entries[j - 1];
125	            j = j - 1;
126	        }
127	
128	        // 새 엔트리 삽입
129	        si.entries[pos] = StrIndexEntry{
130	            key:    key,
131	            row_id: row_id,
132	        };
133	        si.entry_count = si.entry_count + 1;
134	        return STR_IDX_OK;
135	    }
136	
137	    // === 검색 함수 ===
138	
139	    // EQ 검색: 정확 일치하는 키 검색
140	    // 반환: (row_id, 찾음 여부)
141	    func (si: *StrIndex) str_search(key: string) -> (i64, bool) {
142	        let i = 0;
143	        for i = 0; i < si.entry_count; i = i + 1 {
144	            if si.entries[i].key == key {
145	                return (si.entries[i].row_id, true);
146	            }
147	        }
148	        return (0, false);
149	    }
150	
151	    // 이진 검색을 사용한 EQ 검색 (더 빠름)
152	    // 소팅된 배열에서 O(log n) 성능
153	    func (si: *StrIndex) str_search_binary(key: string) -> (i64, bool) {
154	        let left = 0;
155	        let right = si.entry_count - 1;
156	
157	        for left <= right {
158	            let mid = left + (right - left) / 2;
159	            let cmp = str_cmp(key, si.entries[mid].key);
160	
161	            if cmp == 0 {
162	                return (si.entries[mid].row_id, true);
163	            }
164	
165	            if cmp < 0 {
166	                right = mid - 1;
167	            } else {
168	                left = mid + 1;
169	            }
170	        }
171	
172	        return (0, false);
173	    }
174	
175	    // LIKE 검색: 접두어 일치하는 모든 키 검색
176	    // 반환: ([row_id 배열], 찾은 개수)
177	    func (si: *StrIndex) str_like(prefix: string) -> ([i64], i32) {
178	        let result = make([i64], MAX_STR_ENTRIES);
179	        let result_count = 0;
180	
181	        let i = 0;
182	        for i = 0; i < si.entry_count && result_count < MAX_STR_ENTRIES; i = i + 1 {
183	            if str_starts_with(si.entries[i].key, prefix) {
184	                result[result_count] = si.entries[i].row_id;
185	                result_count = result_count + 1;
186	            }
187	        }
188	
189	        return (result, result_count);
190	    }
191	
192	    // 범위 검색: from <= key <= to (사전식 순서)
193	    // 반환: ([row_id 배열], 찾은 개수)
194	    func (si: *StrIndex) str_range(from: string, to: string) -> ([i64], i32) {
195	        let result = make([i64], MAX_STR_ENTRIES);
196	        let result_count = 0;
197	
198	        let i = 0;
199	        for i = 0; i < si.entry_count && result_count < MAX_STR_ENTRIES; i = i + 1 {
200	            let cmp_from = str_cmp(si.entries[i].key, from);
201	            let cmp_to = str_cmp(si.entries[i].key, to);
202	
203	            // from <= key && key <= to
204	            if cmp_from >= 0 && cmp_to <= 0 {
205	                result[result_count] = si.entries[i].row_id;
206	                result_count = result_count + 1;
207	            }
208	        }
209	
210	        return (result, result_count);
211	    }
