215	    // 특정 키와 로우 ID를 가진 엔트리 삭제
216	    // 반환: 성공 여부
217	    func (si: *StrIndex) str_delete(key: string, row_id: i64) -> bool {
218	        let pos = -1;
219	        let i = 0;
220	        for i = 0; i < si.entry_count; i = i + 1 {
221	            if si.entries[i].key == key && si.entries[i].row_id == row_id {
222	                pos = i;
223	                break;
224	            }
225	        }
226	
227	        if pos == -1 {
228	            return false;
229	        }
230	
231	        // 좌측 시프트 (pos 위치 뒤로 모든 원소를 앞으로)
232	        let j = pos;
233	        for j < si.entry_count - 1 {
234	            si.entries[j] = si.entries[j + 1];
235	            j = j + 1;
236	        }
237	        si.entry_count = si.entry_count - 1;
238	        return true;
239	    }
